CREATE TABLE "Collection" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "workspaceId" TEXT NOT NULL, "parentId" TEXT, "position" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3), CONSTRAINT "Collection_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CollectionItem" ("id" TEXT NOT NULL, "collectionId" TEXT NOT NULL, "sourceId" TEXT, "outputId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CollectionItem_pkey" PRIMARY KEY ("id"), CONSTRAINT "CollectionItem_target_check" CHECK (("sourceId" IS NOT NULL)::int + ("outputId" IS NOT NULL)::int = 1));
CREATE TABLE "Tag" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "color" TEXT, "workspaceId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3), CONSTRAINT "Tag_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TagAssignment" ("id" TEXT NOT NULL, "tagId" TEXT NOT NULL, "sourceId" TEXT, "outputId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TagAssignment_pkey" PRIMARY KEY ("id"), CONSTRAINT "TagAssignment_target_check" CHECK (("sourceId" IS NOT NULL)::int + ("outputId" IS NOT NULL)::int = 1));
CREATE TABLE "Favorite" ("id" TEXT NOT NULL, "workspaceId" TEXT NOT NULL, "userId" TEXT NOT NULL, "sourceId" TEXT, "outputId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Favorite_pkey" PRIMARY KEY ("id"), CONSTRAINT "Favorite_target_check" CHECK (("sourceId" IS NOT NULL)::int + ("outputId" IS NOT NULL)::int = 1));
CREATE TABLE "ShareLink" ("id" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "workspaceId" TEXT NOT NULL, "userId" TEXT NOT NULL, "sourceId" TEXT, "outputId" TEXT, "expiresAt" TIMESTAMP(3), "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ShareLink_pkey" PRIMARY KEY ("id"), CONSTRAINT "ShareLink_target_check" CHECK (("sourceId" IS NOT NULL)::int + ("outputId" IS NOT NULL)::int = 1));
CREATE TABLE "OutputVersion" ("id" TEXT NOT NULL, "outputId" TEXT NOT NULL, "event" TEXT NOT NULL, "title" TEXT NOT NULL, "content" JSONB NOT NULL, "metadata" JSONB, "provider" TEXT NOT NULL, "model" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "OutputVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WorkspacePreference" ("id" TEXT NOT NULL, "workspaceId" TEXT NOT NULL, "defaultProvider" TEXT NOT NULL DEFAULT 'openai', "defaultModel" TEXT NOT NULL DEFAULT 'gpt-4o-mini', "language" TEXT NOT NULL DEFAULT 'en', "theme" TEXT NOT NULL DEFAULT 'system', "defaultExportFormat" TEXT NOT NULL DEFAULT 'markdown', "streaming" BOOLEAN NOT NULL DEFAULT true, "autosave" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WorkspacePreference_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CollectionItem_collectionId_sourceId_key" ON "CollectionItem"("collectionId", "sourceId"); CREATE UNIQUE INDEX "CollectionItem_collectionId_outputId_key" ON "CollectionItem"("collectionId", "outputId"); CREATE INDEX "Collection_workspaceId_parentId_position_idx" ON "Collection"("workspaceId", "parentId", "position"); CREATE INDEX "Collection_workspaceId_deletedAt_idx" ON "Collection"("workspaceId", "deletedAt");
CREATE UNIQUE INDEX "Tag_workspaceId_name_key" ON "Tag"("workspaceId", "name"); CREATE INDEX "Tag_workspaceId_deletedAt_idx" ON "Tag"("workspaceId", "deletedAt"); CREATE UNIQUE INDEX "TagAssignment_tagId_sourceId_key" ON "TagAssignment"("tagId", "sourceId"); CREATE UNIQUE INDEX "TagAssignment_tagId_outputId_key" ON "TagAssignment"("tagId", "outputId");
CREATE UNIQUE INDEX "Favorite_userId_sourceId_key" ON "Favorite"("userId", "sourceId"); CREATE UNIQUE INDEX "Favorite_userId_outputId_key" ON "Favorite"("userId", "outputId"); CREATE INDEX "Favorite_workspaceId_userId_idx" ON "Favorite"("workspaceId", "userId"); CREATE UNIQUE INDEX "ShareLink_tokenHash_key" ON "ShareLink"("tokenHash"); CREATE INDEX "ShareLink_workspaceId_createdAt_idx" ON "ShareLink"("workspaceId", "createdAt"); CREATE INDEX "OutputVersion_outputId_createdAt_idx" ON "OutputVersion"("outputId", "createdAt"); CREATE UNIQUE INDEX "WorkspacePreference_workspaceId_key" ON "WorkspacePreference"("workspaceId");
